/// <summary>
/// use to update the displayContainer
/// </summary>
/// <param name = "_displayContainer">
/// the to update display container
/// </param>
/// <param name = "_searchNumber">
/// the search number for the display control
/// </param>
/// <param name = "_searchValue">
/// the search value for the display control
/// </param>
/// <param name = "_setNumber">
/// the set number for the display control
/// </param>
/// <param name = "_setValue">
/// the set value for the display control
/// </param>
/// <param name = "_isDisplayContainer">
/// if a display container or display control
/// </param>
/// <returns>
/// the changed or origan display container or display control
/// </returns>
static container updateDisplayContainer(container    _displayContainer,
                                        int          _searchNumber,
                                        anytype      _searchValue,
                                        int          _setNumber,
                                        anytype      _setValue,
                                        boolean      _isDisplayContainer = true)
{
    Counter controlCount;

    container   controlsElement;

    for (controlCount = AVAWHSWorkExecuteDisplayHelper::getContainerStartValue(_isDisplayContainer); controlCount <= conLen(_displayContainer); controlCount++)
    {
        controlsElement = conPeek(_displayContainer, controlCount);

        if (AVAWHSWorkExecuteDisplayHelper::checkControlElementsLength(conLen(controlsElement)))
        {
            if (conPeek(controlsElement, _searchNumber) == _searchValue)
            {
                controlsElement = conPoke(controlsElement, _setNumber,_setValue);

                _displayContainer = conPoke(_displayContainer, controlCount, controlsElement) ;

                return _displayContainer;
            }
        }
    }

    return _displayContainer;
}

/// <summary>
/// use to check the displayContainer
/// </summary>
/// <param name = "_displayContainer">
/// the to update display container
/// </param>
/// <param name = "_searchNumber">
/// the search number for the display control
/// </param>
/// <param name = "_searchValue">
/// the search value for the display control
/// </param>
/// <param name = "_isDisplayContainer">
/// if a display container or display control
/// </param>
/// <returns>
/// exists the container or not
/// </returns>
static boolean existDisplayContainer(container    _displayContainer,
                                     int          _searchNumber,
                                     anytype      _searchValue,
                                     boolean      _isDisplayContainer = true)
{
    Counter     controlCount;
    container   controlsElement;


    for (controlCount = AVAWHSWorkExecuteDisplayHelper::getContainerStartValue(_isDisplayContainer); controlCount <= conLen(_displayContainer); controlCount++)
    {
        controlsElement = conPeek(_displayContainer,controlCount);

        if (AVAWHSWorkExecuteDisplayHelper::checkControlElementsLength(conLen(controlsElement)))
        {
            if (conPeek(controlsElement,_searchNumber) == _searchValue)
            {
                return true;
            }
        }
    }

    return false;
}

/// <summary>
/// use to get the data value the displayContainer
/// </summary>
/// <param name = "_displayContainer">
/// the to update display container
/// </param>
/// <param name = "_searchNumber">
/// the search number for the display control
/// </param>
/// <param name = "_searchValue">
/// the search value for the display control
/// </param>
/// <param name = "_isDisplayContainer">
/// if a display container or display control
/// </param>
/// <returns>
/// returns the data from the control as string
/// </returns>
static str getdisplayContainerData(container    _displayContainer,
                                   int          _searchNumber,
                                   anytype      _searchValue,
                                   boolean      _isDisplayContainer = true)
{

    Counter     controlCount;
    container   controlsElement;
    str         data;

    for (controlCount = AVAWHSWorkExecuteDisplayHelper::getContainerStartValue(_isDisplayContainer); controlCount <= conLen(_displayContainer); controlCount++)
    {
        controlsElement = conPeek(_displayContainer, controlCount);

        if (AVAWHSWorkExecuteDisplayHelper::checkControlElementsLength(conLen(controlsElement)))
        {
            if (conPeek(controlsElement,_searchNumber) == _searchValue)
            {
                data = conPeek(controlsElement, #Data);

                return data;
            }
        }
    }

    return data;
}

