/// <summary>
/// use to insert a new control into the display container 
/// </summary>
/// <param name = "_displayContainer">
/// the to update display container
/// </param>
/// <param name = "_searchNumber">
/// the search number for the display control
/// </param>
/// <param name = "_searchValue">
/// the search value for the display control
/// </param>
/// <param name = "_insertdisplayContainer">
/// the new control
/// </param>
/// <param name = "controlPosition">
/// the postion where we add the control
/// </param>
/// <param name = "_isDisplayContainer">
/// if a display container or display control
/// </param>
/// <returns>
/// returns the modify new display container
/// </returns>
static container insertDisplayContainer(container    _displayContainer,
                                        int          _searchNumber,
                                        anytype      _searchValue,
                                        container    _insertdisplayContainer,
                                        Counter      controlPosition = 1,           // 1 = below And 0 = above
                                        boolean      _isDisplayContainer = true)
{
    Counter             controlCount;

    container           controlsElement;

    for (controlCount = AVAWHSWorkExecuteDisplayHelper::getContainerStartValue(_isDisplayContainer); controlCount <= conLen(_displayContainer); controlCount++)
    {
        controlsElement = conPeek(_displayContainer, controlCount);

        if (AVAWHSWorkExecuteDisplayHelper::checkControlElementsLength(conLen(controlsElement)))
        {
            if (conPeek(controlsElement, _searchNumber) == _searchValue)
            {
                _displayContainer = conIns(_displayContainer, controlCount + controlPosition, _insertdisplayContainer);

                return _displayContainer;
            }
        }
    }

    return _displayContainer;
}

/// <summary>
/// use to remove a control from the display container
/// </summary>
/// <param name = "_displayContainer">
/// the to update display container
/// </param>
/// <param name = "_searchNumber">
/// the search number for the display control
/// </param>
/// <param name = "_searchValue">
/// the search value for the display control
/// </param>
/// <param name = "_insertdisplayContainer">
/// the new control
/// </param>
/// <returns>
/// returns the modify new display container
/// </returns>
static container removeDisplayContainer(container    _displayContainer,
                                        int          _searchNumber,
                                        anytype      _searchValue,
                                        boolean      _isDisplayContainer = true)
{
    Counter     controlCount;
    container   controlsElement;

    for (controlCount = AVAWHSWorkExecuteDisplayHelper::getContainerStartValue(_isDisplayContainer); controlCount <= conLen(_displayContainer); controlCount++)
    {
        controlsElement = conPeek(_displayContainer,controlCount);

        if (AVAWHSWorkExecuteDisplayHelper::checkControlElementsLength(conLen(controlsElement)))
        {
            if (conPeek(controlsElement, _searchNumber) == _searchValue)
            {
                _displayContainer = conDel(_displayContainer, controlCount, 1);

                return _displayContainer;
            }
        }
    }

    return _displayContainer;
}

private static Counter getContainerStartValue(boolean _isDisplayContainer = true) //true for displaycontainer and false für buildControls Container
{
    Counter counter;

    if (_isDisplayContainer)
    {
        counter = #FirstDataLine;
    }
    else
    {
        counter = #FirstLine;
    }

    return counter;
}

private static boolean checkControlElementsLength(int ControlElementsLength)
{
    boolean isValid;

    switch (ControlElementsLength)
    {
        case #ControlElementsLengthVersion1:
        case #ControlElementsLengthVersion2:
        case #ControlElementsLengthVersion3:
        case #ControlElementsLengthVersion4:
        case #ControlElementsLengthVersion5:
        case #ControlElementsLengthVersion6:
        case #ControlElementsLengthVersion7:
        case #ControlElementsLengthVersion8:
            isValid = true;
            break;
    }

    return isValid;
}
